      COMPLEX*16 ALINEMOM223,ALINEMOM224,ALINEMOM225,ALINEMOM226
      COMPLEX*16 ALINEMOM227,ALINEMOM228,ALINEMOM229,ALINEMOM230
      COMPLEX*16 ALINEMOM231,ALINEMOM232,ALINEMOM233,ALINEMOM234
      COMPLEX*16 ALINEMOM235
!**********************************************************************
      COMPLEX*16 CSUMSMOM(4,2),CSUM2SMOM(4,2),CSUM2WSMOM(4,2)
      COMPLEX*16 CSUMWMOM(4,2),CSUM2WMOM(4,2),CSUM3WMOM(4,2)
      COMPLEX*16 CSUMUPMOM(4,2),CSUMUDMOM(4,2)
!
      COMPLEX*16 CSUMPLQMOM(8,2),CSUMPLQMOM2(8,2),CSUMPLQMOM3(8,2)
      COMPLEX*16 CSUMPLQMOM4(8,2),CSUMPLQMOM5(8,2),CSUMPLQMOM6(8,2)
      COMPLEX*16 CSUMPLQMOM7(16,2), CSUMPLQMOM8(16,2)
      COMPLEX*16 CSUMPLQMOM9(16,2), CSUMPLQMOM10(16,2)
      COMPLEX*16 CSUMPLQMOM11(16,2), CSUMPLQMOM12(16,2)
      COMPLEX*16 CSUMPLQMOM13(16,2), CSUMPLQMOM14(16,2)
      COMPLEX*16 CSUMPLQMOM15(16,2)
!     
      COMPLEX*16 CSUMTTMOM1(8,2),CSUMTTMOM2(8,2),CSUMTTMOM3(8,2)
      COMPLEX*16 CSUMTTMOM4(8,2),CSUMTTMOM5(8,2),CSUMTTMOM6(8,2)
      COMPLEX*16 CSUMTTMOM7(8,2),CSUMTTMOM8(8,2),CSUMTTMOM9(8,2)
      COMPLEX*16 CSUMTTMOM10(8,2),CSUMTTMOM11(8,2)
      COMPLEX*16 CSUMTTMOM12(16,2)
      COMPLEX*16 CSUMTTMOM13(8,2),CSUMTTMOM14(8,2)
!
      COMPLEX*16 GIOT,PF(2)
      COMPLEX UREN11(NCOL2)
      COMPLEX AA(NCOL2)
      COMPLEX DET,CNORM,CDET,DNCOL
!**********************************************************************
      GIOT=(0.0,1.0)
      PI=4.0d0*DATAN(1.0d0)
      LS(1)=LX1
      LS(2)=LX2
      LS(3)=LX3
      LB(1)=1
!*********************************************************************     
! LB is an array containing the blocking length at each level
      DO IDD=2,IBLOK
         LB(IDD)=2*LB(IDD-1)
      ENDDO
!********************************************************************* 
      KU = 1 ! Set directions -- X
      JU = 2 ! Y
      IU = 3 ! Z
     
      ID=IBLL ! Current blocking level (BL)


! We try and fit the blocking level lengths into LX1
! Fill LCNT array 
! Example: LX1 = 20, IBL=4
! LCNT = 0, 0, 1, 2

      DO IB=1,ID
         LCNT(IB)=0
      ENDDO

      LREST=LS(KU) ! LX1

      DO IDG=1,ID,-1
         LCNT(IDG)=LREST/LB(IDG)
         LREST=LREST-LCNT(IDG)*LB(IDG)
      ENDDO

 ! Find the largest blocking level IDS which fits more than
 ! one link in the lattice X direction
 ! (in which case it makes sense to define of a Polyakov loop)
      DO IB=1,ID
         IF(LCNT(IB).GE.1) THEN
           IDS=IB
         ENDIF
      ENDDO

 ! Blocking level below IDS - if it's the smallest, set it to itself
 ! Only happens if LX1 = 2 (I think)
      IDSM1=IDS-1
      IF(IDS.EQ.1)IDSM1=IDS
!**********************************************************************
! Use this to set the move functions at the correct blocking level
! Use the move functions of the IDS blocking level
! TODO: Source of duplicate operators, should also have possible
!       optimisation as it's called at every BL
      DO KK=1,3
         DO NN=1,LSIZEB
            IUP(NN,KK)=IUPB(NN,KK,IDS)
            IDN(NN,KK)=IDNB(NN,KK,IDS)
         ENDDO
      ENDDO
!**********************************************************************    
! Define our configuration at the current blocking level
! to be the configuration at BL corresponding to IDS
      DO KK=1,3
         DO NN=1,LSIZEB
            DO IC=1,NCOL2
               UC11(IC,NN,KK)=UB11(IC,NN,KK,IDS)
            ENDDO
         ENDDO
      ENDDO
!**********************************************************************
! These sums keep track of the operators, summing them to make
! the final operator is translation invariant
      CSUMN=(0.0,0.0)
! These operators have 4 rotations
      DO IJN=1,4
                              ! Each element will be summed over
                              ! all x
                              ! and contains one ''rotation''
         CSUMS(IJN)=(0.0,0.0)
         CSUM2S(IJN)=(0.0,0.0)
         CSUM2WS(IJN)=(0.0,0.0)
         CSUMW(IJN)=(0.0,0.0)
         CSUM2W(IJN)=(0.0,0.0)
         CSUM3W(IJN)=(0.0,0.0)
         CSUMUP(IJN)=(0.0,0.0)
         CSUMUD(IJN)=(0.0,0.0)
      ENDDO
! These operators have 4 rotations x 2 reflections
      DO IJN=1,8
         CSUMTT1(IJN)=(0.0,0.0)
         CSUMTT2(IJN)=(0.0,0.0)
         CSUMTT3(IJN)=(0.0,0.0)
         CSUMTT4(IJN)=(0.0,0.0)
         CSUMTT5(IJN)=(0.0,0.0)
         CSUMTT6(IJN)=(0.0,0.0)
         CSUMTT7(IJN)=(0.0,0.0)
         CSUMTT8(IJN)=(0.0,0.0)
         CSUMTT9(IJN)=(0.0,0.0)
         CSUMTT10(IJN)=(0.0,0.0)
         CSUMTT11(IJN)=(0.0,0.0)
         CSUMTT13(IJN)=(0.0,0.0)
         CSUMTT14(IJN)=(0.0,0.0)
         CSUMPLQ(IJN)=(0.0,0.0)
         CSUMPLQ2(IJN)=(0.0,0.0)
         CSUMPLQ3(IJN)=(0.0,0.0)
         CSUMPLQ4(IJN)=(0.0,0.0)
         CSUMPLQ5(IJN)=(0.0,0.0)
         CSUMPLQ6(IJN)=(0.0,0.0)
      ENDDO
! These operators have 4 rotations x 2 reflections
!                                  x 2 reflection
! from different parities
      DO IJN=1,16
         CSUMTT12(IJN)=(0.0,0.0)
         CSUMPLQ7(IJN)=(0.0,0.0)
         CSUMPLQ8(IJN)=(0.0,0.0)
         CSUMPLQ9(IJN)=(0.0,0.0)
         CSUMPLQ10(IJN)=(0.0,0.0)
         CSUMPLQ11(IJN)=(0.0,0.0)
         CSUMPLQ12(IJN)=(0.0,0.0)
         CSUMPLQ13(IJN)=(0.0,0.0)
         CSUMPLQ14(IJN)=(0.0,0.0)
         CSUMPLQ15(IJN)=(0.0,0.0)
      ENDDO
!CCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCC
! Same as operators above but adding momentum
      DO IJN=1, 4 ! index the rotations
         DO IJ=1, 2 ! indexes J1, J2
            CSUMSMOM(IJN,IJ)=(0.0,0.0)
            CSUM2SMOM(IJN,IJ)=(0.0,0.0)
            CSUM2WSMOM(IJN,IJ)=(0.0,0.0)
            CSUMWMOM(IJN,IJ)=(0.0,0.0)
            CSUM2WMOM(IJN,IJ)=(0.0,0.0)
            CSUM3WMOM(IJN,IJ)=(0.0,0.0)
            CSUMUPMOM(IJN,IJ)=(0.0,0.0)
            CSUMUDMOM(IJN,IJ)=(0.0,0.0)
         ENDDO
      ENDDO
!CCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCC
      DO IJN=1, 8
         DO IJ=1, 2
            CSUMTTMOM1(IJN,IJ)=(0.0,0.0)
            CSUMTTMOM2(IJN,IJ)=(0.0,0.0)
            CSUMTTMOM3(IJN,IJ)=(0.0,0.0)
            CSUMTTMOM4(IJN,IJ)=(0.0,0.0)
            CSUMTTMOM5(IJN,IJ)=(0.0,0.0)
            CSUMTTMOM6(IJN,IJ)=(0.0,0.0)
            CSUMTTMOM7(IJN,IJ)=(0.0,0.0)
            CSUMTTMOM8(IJN,IJ)=(0.0,0.0)
            CSUMTTMOM9(IJN,IJ)=(0.0,0.0)
            CSUMTTMOM10(IJN,IJ)=(0.0,0.0)
            CSUMTTMOM11(IJN,IJ)=(0.0,0.0)
            CSUMTTMOM13(IJN,IJ)=(0.0,0.0)
            CSUMTTMOM14(IJN,IJ)=(0.0,0.0)
!CCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCC
            CSUMPLQMOM(IJN,IJ)=(0.0,0.0)
            CSUMPLQMOM2(IJN,IJ)=(0.0,0.0)
            CSUMPLQMOM3(IJN,IJ)=(0.0,0.0)
            CSUMPLQMOM4(IJN,IJ)=(0.0,0.0)
            CSUMPLQMOM5(IJN,IJ)=(0.0,0.0)
            CSUMPLQMOM6(IJN,IJ)=(0.0,0.0)
         ENDDO
      ENDDO
! Note: While P_// is not well defined here due to J != 0,
! we double the operators for cross checking and
! extra statistics
      DO IJN=1, 16
         DO IJ=1, 2
            CSUMTTMOM12(IJN,IJ)=(0.0,0.0)
            CSUMPLQMOM7(IJN,IJ)=(0.0,0.0)
            CSUMPLQMOM8(IJN,IJ)=(0.0,0.0)
            CSUMPLQMOM9(IJN,IJ)=(0.0,0.0)
            CSUMPLQMOM10(IJN,IJ)=(0.0,0.0)
            CSUMPLQMOM11(IJN,IJ)=(0.0,0.0)
            CSUMPLQMOM12(IJN,IJ)=(0.0,0.0)
            CSUMPLQMOM13(IJN,IJ)=(0.0,0.0)
            CSUMPLQMOM14(IJN,IJ)=(0.0,0.0)
            CSUMPLQMOM15(IJN,IJ)=(0.0,0.0)
         ENDDO
      ENDDO
!
!**********************************************************************

       NN=0 ! Initial lattice point
       DO NK=1,LS(KU) ! LX direction
          ! Momentum phases
          PF(1)=DCOS((2.0*PI*NK)/LS(KU))+GIOT*DSIN((2.0*PI*NK)/LS(KU))
          PF(2)=DCOS((4.0*PI*NK)/LS(KU))+GIOT*DSIN((4.0*PI*NK)/LS(KU))
             DO NJ=1,LS(JU) ! LY direction
                DO NI=1,LS(IU) ! LZ direction 
                   ! Lexicographical lattice site definition
                   NN=NN+1
                   IX(IU)=NI
                   IX(JU)=NJ
                   IX(KU)=NK
                   ! MN defines the current lattice site
                   MN=IX(1)+LS(1)*(IX(2)-1)+LS(1)*LS(2)*(IX(3)-1)


! TODO: ANDREAS COMMENTS FROM HERE
!**********************************************************************
                   IF(IDS.EQ.ID) THEN
!**********************************************************************
                      IREM=3
                      IF(IDS.EQ.1) IREM=4
                      DO ILOOP=1,IREM
                         IF(ILOOP.EQ.1)LI=LCNT(IDS)
                         IF(ILOOP.GT.1)LI=LCNT(IDS)-2**(ILOOP-2)
                         IF(LI.LT.0) EXIT
!      
                         M2=MN
                         IF(ILOOP.GT.1) THEN
                            DO I=1, 2**(ILOOP-2)
                               M3=IUP(M2,KU)
                               M2=M3
                            END DO
                         ENDIF
!
                         DO IC=1,NCOL2                        
                            E11(IC)=(0.0,0.0)
                         ENDDO
!
                         DO N1=1,NCOL                         
                            IJ=N1+NCOL*(N1-1)                     
                            E11(IJ)=(1.0,0.0)                     
                         ENDDO
!
                         DO NC=1,LI
                            DO  IC=1,NCOL2
                               B11(IC)=UC11(IC,M2,KU)
                            ENDDO
                            CALL VMX(1,E11,B11,C11,1)
                            M3=IUP(M2,KU)
                            M2=M3
                            DO IC=1,NCOL2
                               E11(IC)=C11(IC)
                            ENDDO
                         ENDDO
!
                         ML=M2
                         IF(ILOOP.EQ.1) THEN
                            DO IC=1,NCOL2
                               LIN0(IC)=E11(IC)
                            ENDDO
                         ENDIF
!********************************************************************                  
                        IF(ILOOP.EQ.2) THEN
                           DO IC=1,NCOL2
                              LIN1(IC)=E11(IC)   
                           ENDDO
                        ENDIF
!********************************************************************                                 
                        IF(ILOOP.EQ.3) THEN
                           DO IC=1,NCOL2
                              LIN2(IC)=E11(IC)   
                           ENDDO
                        ENDIF
!********************************************************************
                        IF(ILOOP.EQ.4) THEN
                           DO IC=1,NCOL2
                              LIN4(IC)=E11(IC)   
                           ENDDO
                        ENDIF
!********************************************************************
                     ENDDO
!CCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCC
                  ELSE
                     M2=MN
                  ENDIF
!**********************************************************************
!*********************** REMAINING PIECE ******************************
!**********************************************************************            
                  DO IC=1, NCOL2
                     REM11(IC)=(0.0,0.0)
                  ENDDO
!********************************************************************
                  DO N1=1,NCOL
                     IJ=N1+NCOL*(N1-1)                     
                     REM11(IJ)=(1.0,0.0) 
                  ENDDO
!********************************************************************
                  DO IG=1,IDS
                      IDG=IDS-IG+1
                      IF(IDG.EQ.ID) CYCLE
                      DO NC=1,LCNT(IDG)

                         DO IC=1,NCOL2
                            UINT11(IC)=(0.0,0.0)
                         ENDDO
!     
                         DO IJ=1,3
                            IF(IJ.EQ.KU) CYCLE
                            DO IC=1,NCOL2
                               B11(IC)=UB11(IC,M2,IJ,IDSM1)
                            ENDDO
                            M3=IUPB(M2,IJ,IDSM1)
                            DO IC=1,NCOL2
                               C11(IC)=UB11(IC,M3,KU,IDG)
                            ENDDO
                            CALL VMX(1,B11,C11,D11,1)
                            M1=IUPB(M2,KU,IDG)
                            DO IC=1,NCOL2
                               B11(IC)=UB11(IC,M1,IJ,IDSM1)
                            ENDDO
                            CALL HERM(1,B11,DUM11,1)
                            CALL VMX(1,D11,B11,C11,1)
                            DO IC=1,NCOL2
                               UINT11(IC)=UINT11(IC)+C11(IC)
                            ENDDO
                            M3=IDNB(M2,IJ,IDSM1)
                            DO IC=1,NCOL2
                               B11(IC)=UB11(IC,M3,IJ,IDSM1)
                            ENDDO
                            DO IC=1,NCOL2
                               C11(IC)=UB11(IC,M3,KU,IDG)
                            ENDDO
                            CALL HERM(1,B11,DUM11,1)
                            CALL VMX(1,B11,C11,D11,1)
                            M1=IUPB(M3,KU,IDG)
                            DO IC=1,NCOL2
                               B11(IC)=UB11(IC,M1,IJ,IDSM1)
                            ENDDO
                            CALL VMX(1,D11,B11,C11,1)
                            DO IC=1,NCOL2
                               UINT11(IC)=UINT11(IC)+C11(IC)
                            ENDDO
                         ENDDO
                         DO IC=1,NCOL2
                            B11(IC)=UB11(IC,M2,KU,IDG)
                         ENDDO
                         DO IC=1,NCOL2
                            UINT11(IC)=UINT11(IC)+B11(IC)
                         ENDDO
!
                         CALL RENORMBS(UINT11,UREN11)
                         DO IJ=1,NCOL2
                            AA(IJ)=UREN11(IJ)
                         ENDDO
                         JMAT=NCOL
                         CALL DETNANT(JMAT,DET,AA)
!
                         DNCOL=CMPLX(1.0/NCOL)
                         CDET=DET**DNCOL
                         CNORM=1.0/CDET
!
                         DO IC=1,NCOL2
                            B11(IC)=UREN11(IC)*CNORM
                         ENDDO
!*************************************************************
                         CALL VMX(1,REM11,B11,C11,1)
                         M1=M2
                         DO IC=1,NCOL2
                            REM11(IC)=C11(IC)
                         ENDDO
                         M2=IUPB(M1,KU,IDG)
                      ENDDO
                   ENDDO
!CCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCC
! OPERATOR CONSTRUCTION
                   DO 9 IDDD=1,337 !new!
!
                      M2=MN
!
                      DO IJ=1,NCOL2
                         A11(IJ)=(0.0,0.0)
                      ENDDO
!
                      DO N1=1,NCOL
                         IJ=N1+NCOL*(N1-1)
                         A11(IJ)=(1.0,0.0)
                      ENDDO
!CCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCC
                      IF (IDS.EQ.ID) THEN
!CCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCC
                         ICO=2
                         IF(IDDD.LT.5) ICO=1
                         IF(((IDDD.GT.12).AND.(IDDD.LT.17)).AND.(IDS.NE.1)) ICO=1
                         IF(((IDDD.GT.16).AND.(IDDD.LT.21)).AND.(IDS.EQ.1)) ICO=4
                         IF(((IDDD.GT.20).AND.(IDDD.LT.25)).AND.(IDS.EQ.1)) ICO=4
                         IF(((IDDD.GT.24).AND.(IDDD.LT.29)).AND.(IDS.EQ.1)) ICO=4
                         IF(((IDDD.GT.28).AND.(IDDD.LT.33)).AND.(IDS.EQ.1)) ICO=4
                         IF(((IDDD.GT.40).AND.(IDDD.LT.49)).AND.(IDS.EQ.1)) ICO=4
                         IF(((IDDD.GT.48).AND.(IDDD.LT.57)).AND.(IDS.EQ.1)) ICO=4
                         IF(((IDDD.GT.56).AND.(IDDD.LT.65)).AND.(IDS.EQ.1)) ICO=4
                         IF(((IDDD.GT.64).AND.(IDDD.LT.69)).AND.(IDS.EQ.1)) ICO=4
                         IF(((IDDD.GT.68).AND.(IDDD.LT.73)).AND.(IDS.EQ.1)) ICO=4
                         IF(((IDDD.GT.72).AND.(IDDD.LT.81)).AND.(IDS.EQ.1)) ICO=4
                         IF(((IDDD.GT.80).AND.(IDDD.LT.89)).AND.(IDS.EQ.1)) ICO=4
                         IF(((IDDD.GT.88).AND.(IDDD.LT.97)).AND.(IDS.EQ.1)) ICO=4
                         IF(((IDDD.GT.96).AND.(IDDD.LT.105)).AND.(IDS.EQ.1)) ICO=4
                         IF(((IDDD.GT.104).AND.(IDDD.LT.113)).AND.(IDS.EQ.1)) ICO=4
                         IF(((IDDD.GT.112).AND.(IDDD.LT.129)).AND.(IDS.EQ.1)) ICO=4
                         IF(((IDDD.GT.128).AND.(IDDD.LT.137)).AND.(IDS.EQ.1)) ICO=4
                         IF(((IDDD.GT.136).AND.(IDDD.LT.145)).AND.(IDS.NE.1)) ICO=1
                         IF(IDDD.EQ.145) ICO=1
                         IF((IDDD.GT.145).AND.(IDDD.LT.194)) ICO=1
                         IF((IDDD.GT.209).AND.(IDDD.LT.338)) ICO=1 ! THIS NEEDS TO BE FIXED  !
!**********************************************************************C
                         IF(LCNT(IDS).GE.ICO) THEN
!**********************************************************************C
!                     UP SQUARE PULSE                                  C 
!**********************************************************************C
!                     UP Y
!**********************************************************************
                         IF(IDDD.EQ.1) THEN
!
                            DO IC=1,NCOL2
                               B11(IC)=UC11(IC,M2,JU)
                            ENDDO
                            M3=IUP(M2,JU)
                            DO IC=1,NCOL2
                               C11(IC)=UC11(IC,M3,KU)
                            ENDDO
                            CALL VMX(1,B11,C11,D11,1)
                            M3=IUP(M2,KU)
                            M2=M3
                            DO IC=1,NCOL2
                               C11(IC)=UC11(IC,M2,JU)
                            ENDDO
                            CALL HERM(1,C11,DUM11,1)
                            CALL VMX(1,D11,C11,SQUY1,1)
                            CALL VMX(1,A11,SQUY1,C11,1)
!     
                            DO IC=1,NCOL2
                               A11(IC)=C11(IC)
                            ENDDO
!     
                            IEEE=1
!     
                        ENDIF
!**********************************************************************C
!     UP Z                                                             C 
!**********************************************************************C
                        IF(IDDD.EQ.2) THEN
!     
                           DO 16 IC=1,NCOL2
                              B11(IC)=UC11(IC,M2,IU)
 16                        CONTINUE
                           M3=IUP(M2,IU)
                           DO 17 IC=1,NCOL2
                              C11(IC)=UC11(IC,M3,KU)
 17                        CONTINUE
                           CALL VMX(1,B11,C11,D11,1)
                           M3=IUP(M2,KU)
                           M2=M3
                           DO 18 IC=1,NCOL2
                              C11(IC)=UC11(IC,M2,IU)
 18                        CONTINUE
                           CALL HERM(1,C11,DUM11,1)
                           CALL VMX(1,D11,C11,SQUZ1,1)
                           CALL VMX(1,A11,SQUZ1,C11,1)
!     
                           DO 19 IC=1,NCOL2
                              A11(IC)=C11(IC)
 19                        CONTINUE
!     
                           IEEE=2
!     
                        ENDIF
!**********************************************************************C 
!                       DOWN Y                                         C
!**********************************************************************C
                        IF(IDDD.EQ.3) THEN
!     
                           M3=IDN(M2,JU)
                           DO 20 IC=1,NCOL2
                              D11(IC)=UC11(IC,M3,JU)
 20                        CONTINUE
                           CALL HERM(1,D11,DUM11,1)
                           DO 21 IC=1,NCOL2
                              C11(IC)=UC11(IC,M3,KU)
 21                        CONTINUE
                           CALL VMX(1,D11,C11,B11,1)
                           M4=IUP(M3,KU)
                           DO 22 IC=1,NCOL2
                              D11(IC)=UC11(IC,M4,JU)
 22                        CONTINUE
                           CALL VMX(1,B11,D11,SQDY1,1)
                           CALL VMX(1,A11,SQDY1,C11,1)
!     
                           DO 23 IC=1,NCOL2
                              A11(IC)=C11(IC)
 23                        CONTINUE
!     
                           IEEE=3
!     
                        ENDIF
!**********************************************************************C 
!                       DOWN Z                                 C
!**********************************************************************C
                        IF(IDDD.EQ.4) THEN
!     
                           M3=IDN(M2,IU)
                           DO 24 IC=1,NCOL2
                              D11(IC)=UC11(IC,M3,IU)
 24                        CONTINUE
                           CALL HERM(1,D11,DUM11,1)
                           DO 25 IC=1,NCOL2
                              C11(IC)=UC11(IC,M3,KU)
 25                        CONTINUE
                           CALL VMX(1,D11,C11,B11,1)
                           M4=IUP(M3,KU)
                           DO 26 IC=1,NCOL2
                              D11(IC)=UC11(IC,M4,IU)
 26                        CONTINUE
                           CALL VMX(1,B11,D11,SQDZ1,1)
                           CALL VMX(1,A11,SQDZ1,C11,1)
!     
                           DO 27 IC=1,NCOL2
                              A11(IC)=C11(IC)
 27                        CONTINUE
!     
                           IEEE=4
!     
                        ENDIF
!**********************************************************************C
!                       UP - UP SQUARE PULSES                         *C 
!**********************************************************************C
!                       UP Y
!**********************************************************************C
                        IF(IDDD.EQ.5) THEN
!     
                           M3=IUP(M2,KU)
                           DO 28 IC=1,NCOL2
                              D11(IC)=UC11(IC,M3,JU)
 28                        CONTINUE
                           M4=IUP(M3,JU)
                           DO 29 IC=1,NCOL2
                              C11(IC)=UC11(IC,M4,KU)
 29                        CONTINUE
                           CALL VMX(1,D11,C11,B11,1)
                           M2=IUP(M3,KU)
                           DO 30 IC=1,NCOL2
                              C11(IC)=UC11(IC,M2,JU)
 30                        CONTINUE
                           CALL HERM(1,C11,DUM11,1)
                           CALL VMX(1,B11,C11,SQUY2,1)
                           CALL VMX(1,SQUY1,SQUY2,A11,1)
!     
                           IEEE=1
!     
                        ENDIF
!**********************************************************************C
!              UP Z
!**********************************************************************C
                        IF(IDDD.EQ.6) THEN
!     
                           M3=IUP(M2,KU)
                           DO 31 IC=1,NCOL2
                              D11(IC)=UC11(IC,M3,IU)
 31                        CONTINUE
                           M4=IUP(M3,IU)
                           DO 32 IC=1,NCOL2
                              C11(IC)=UC11(IC,M4,KU)
 32                        CONTINUE
                           CALL VMX(1,D11,C11,B11,1)
                           M2=IUP(M3,KU)
                           DO 33 IC=1,NCOL2
                              C11(IC)=UC11(IC,M2,IU)
 33                        CONTINUE
                           CALL HERM(1,C11,DUM11,1)
                           CALL VMX(1,B11,C11,SQUZ2,1)
                           CALL VMX(1,SQUZ1,SQUZ2,A11,1)
!     
                           IEEE=2
!     
                        ENDIF
!**********************************************************************C 
!              DOWN Y                                              C
!**********************************************************************C
                        IF(IDDD.EQ.7) THEN
!     
                           M3=IUP(M2,KU)
                           M4=IDN(M3,JU)
                           DO 34 IC=1,NCOL2
                              D11(IC)=UC11(IC,M4,JU)
 34                        CONTINUE
                           CALL HERM(1,D11,DUM11,1)
                           DO 35 IC=1,NCOL2
                              C11(IC)=UC11(IC,M4,KU)
 35                        CONTINUE
                           CALL VMX(1,D11,C11,B11,1)
                           M1=IUP(M4,KU)
                           DO 36 IC=1,NCOL2
                              C11(IC)=UC11(IC,M1,JU)
 36                        CONTINUE
                           CALL VMX(1,B11,C11,SQDY2,1)
                           CALL VMX(1,SQDY1,SQDY2,A11,1)
                           M2=IUP(M3,KU)
!     
                           IEEE=3
!     
                        ENDIF
!**********************************************************************C 
!              DOWN Z                                              C
!**********************************************************************C
                        IF(IDDD.EQ.8) THEN
!     
                           M3=IUP(M2,KU)
                           M4=IDN(M3,IU)
                           DO 37 IC=1,NCOL2
                              D11(IC)=UC11(IC,M4,IU)
 37                        CONTINUE
                           CALL HERM(1,D11,DUM11,1)
                           DO 38 IC=1,NCOL2
                              C11(IC)=UC11(IC,M4,KU)
 38                        CONTINUE
                           CALL VMX(1,D11,C11,B11,1)
                           M1=IUP(M4,KU)
                           DO 39 IC=1,NCOL2
                              C11(IC)=UC11(IC,M1,IU)
 39                        CONTINUE
                           CALL VMX(1,B11,C11,SQDZ2,1)
                           CALL VMX(1,SQDZ1,SQDZ2,A11,1)
                           M2=IUP(M3,KU)
!     
                           IEEE=4
!     
                        ENDIF
!**********************************************************************C
!**********************************************************************C
!              UP - DOWN SQUARE PULSES                                 C 
!**********************************************************************C
!**********************************************************************C
!                 UP Y 
!**********************************************************************C
                        IF(IDDD.EQ.9) THEN
                           CALL VMX(1,SQUY1,SQDY2,SQUDY1,1)
                           DO IC=1, NCOL2
                              A11(IC)=SQUDY1(IC) !NEW!
                           ENDDO
                           M3=IUP(M2,KU)
                           M2=IUP(M3,KU)
!     
                           IEEE=1
!     
                        ENDIF
!**********************************************************************C
!                 UP Z
!**********************************************************************C
                        IF(IDDD.EQ.10) THEN    
                           CALL VMX(1,SQUZ1,SQDZ2,SQUDZ1,1)
                           DO IC=1, NCOL2
                              A11(IC)=SQUDZ1(IC) !NEW!
                           ENDDO
                           M3=IUP(M2,KU)
                           M2=IUP(M3,KU)
!     
                           IEEE=2
!     
                        ENDIF
!**********************************************************************C 
!                 DOWN Y
!**********************************************************************C
                        IF(IDDD.EQ.11) THEN
                           CALL VMX(1,SQDY1,SQUY2,SQDUY1,1)
                           DO IC=1, NCOL2
                              A11(IC)=SQDUY1(IC) !NEW!
                           ENDDO
                           M3=IUP(M2,KU)
                           M2=IUP(M3,KU)
!     
                           IEEE=3
!     
                        ENDIF
!**********************************************************************C 
!                 DOWN Z
!**********************************************************************C
                        IF(IDDD.EQ.12) THEN
                           CALL VMX(1,SQDZ1,SQUZ2,SQDUZ1,1)
                           DO IC=1, NCOL2
                              A11(IC)=SQDUZ1(IC) !NEW!
                           ENDDO
                           M3=IUP(M2,KU)
                           M2=IUP(M3,KU)
!
                           IEEE=4
!     
                        ENDIF
!**********************************************************************C
!**********************************************************************C
!                 UP WAVE - LIKE PULSE                                *C
!**********************************************************************C
!**********************************************************************C
!                 UP Y
!**********************************************************************C
                  IF(IDDD.EQ.13) THEN
!
                     IDSW=IDS-1
!
                     IF(IDSW.EQ.0) THEN
                        IDSW=1
                     ENDIF
!     
                     DO 40 IC=1,NCOL2
                        D11(IC)=UB11(IC,M2,JU,IDSW)
 40                  CONTINUE
                     M3=IUPB(M2,JU,IDSW)
                     DO 41 IC=1,NCOL2
                        C11(IC)=UB11(IC,M3,KU,IDSW)
 41                  CONTINUE
                     CALL VMX(1,D11,C11,B11,1)
                     M3=IUPB(M2,KU,IDSW)
                     M2=M3
                     DO 42 IC=1,NCOL2
                        C11(IC)=UB11(IC,M2,JU,IDSW)
 42                  CONTINUE
                     CALL HERM(1,C11,DUM11,1)
                     CALL VMX(1,B11,C11,WSQUY1,1)
!                     
                     M3=IDNB(M2,JU,IDSW)
                     DO 43 IC=1,NCOL2
                        B11(IC)=UB11(IC,M3,JU,IDSW)
 43                  CONTINUE
                     CALL HERM(1,B11,DUM11,1)
                     DO 44 IC=1,NCOL2
                        C11(IC)=UB11(IC,M3,KU,IDSW)
 44                  CONTINUE
                     CALL VMX(1,B11,C11,D11,1)
                     M4=IUPB(M3,KU,IDSW)
                     DO 45 IC=1,NCOL2
                        B11(IC)=UB11(IC,M4,JU,IDSW)
 45                  CONTINUE
                     CALL VMX(1,D11,B11,WSQDY2,1)
                     CALL VMX(1,WSQUY1,WSQDY2,WVUY1,1)
                     DO 46 IC=1,NCOL2
                        A11(IC)=WVUY1(IC)
 46                  CONTINUE
                     M3=IUPB(M2,KU,IDSW)
                     M2=M3
!
                        IEEE=1
!
                  ENDIF
!**********************************************************************C
!                 UP Z
!**********************************************************************C
                  IF(IDDD.EQ.14) THEN
!
                     IDSW=IDS-1
!
                     IF(IDSW.EQ.0) THEN
                        IDSW=1
                     ENDIF
!     
                     DO 47 IC=1,NCOL2
                        D11(IC)=UB11(IC,M2,IU,IDSW)
 47                  CONTINUE
                     M3=IUPB(M2,IU,IDSW)
                     DO 48 IC=1,NCOL2
                        C11(IC)=UB11(IC,M3,KU,IDSW)
 48                  CONTINUE
                     CALL VMX(1,D11,C11,B11,1)
                     M3=IUPB(M2,KU,IDSW)
                     M2=M3
                     DO 49 IC=1,NCOL2
                        C11(IC)=UB11(IC,M2,IU,IDSW)
 49                  CONTINUE
                     CALL HERM(1,C11,DUM11,1)
                     CALL VMX(1,B11,C11,WSQUZ1,1)
!                     
                     M3=IDNB(M2,IU,IDSW)
                     DO 50 IC=1,NCOL2
                        B11(IC)=UB11(IC,M3,IU,IDSW)
 50                  CONTINUE
