!**********************************************************************
      DO IK=1, 2
         ALINEMOM226(N4,ID,IK)=(CSUMPLQMOM15(1,IK)+CSUMPLQMOM15(2,IK)&
     +CSUMPLQMOM15(3,IK)+CSUMPLQMOM15(4,IK)&
     +(CSUMPLQMOM15(9,IK)+CSUMPLQMOM15(10,IK)+CSUMPLQMOM15(11,IK)&
     +CSUMPLQMOM15(12,IK)))*ADIV2
      ENDDO
!**********************************************************************      
