      DO IK=1, 2
         ALINEMOM231(N4,ID,IK)=(CSUMPLQMOM15(5,IK)&
     +GIOT*CSUMPLQMOM15(6,IK)&
     -CSUMPLQMOM15(7,IK)-GIOT*CSUMPLQMOM15(8,IK))*ADIV1
