!**********************************************************************
      DO IK=1, 2
         ALINEMOM235(N4,ID,IK)=(CSUMPLQMOM15(5,IK)-CSUMPLQMOM15(6,IK)&
     +CSUMPLQMOM15(7,IK)-CSUMPLQMOM15(8,IK)&
     -(CSUMPLQMOM15(13,IK)-CSUMPLQMOM15(14,IK)+CSUMPLQMOM15(15,IK)&
